/**
 * Random Exam Service
 *
 * Builds a new exam on every attempt of a "random" lab (config.json has a
 * `random` section): it picks a conflict-free mix of tasks from other labs,
 * weighted like the real exam's domains, and writes a regular lab directory
 * (config.json, assessment.json, answers.md, assets.tar.gz) for this attempt.
 * The rest of the facilitator then treats it like any other lab.
 *
 * The pool (pool.json) lists every task with the resources it owns ("claims")
 * and the shared things it relies on ("uses"); it is generated by
 * tools/build-random-pool.py.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');
const logger = require('../utils/logger');

const KEEP_ATTEMPTS = 3;
const extractedSources = new Map();

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function shuffle(items) {
  const a = items.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/**
 * Pick tasks so that no two of them conflict, filling each domain's quota
 * first and topping up from any domain if a quota can't be met.
 * A few tasks block many others (changing the default StorageClass blocks
 * every task that needs it), so several draws are made and the first one
 * that meets every quota wins.
 */
function pickQuestions(pool, count, quotas) {
  let best = null;
  let bestScore = -1;
  const entries = Object.entries(quotas || {});
  for (let attempt = 0; attempt < 200; attempt++) {
    const picked = drawQuestions(pool, count, quotas);
    const score = entries.reduce((sum, [d, n]) => sum + Math.min(n, picked.filter((q) => q.domain === d).length), 0)
      + (picked.length >= count ? 1 : 0);
    if (score > bestScore) {
      best = picked;
      bestScore = score;
    }
    if (picked.length >= count && entries.every(([d, n]) => picked.filter((q) => q.domain === d).length >= n)) break;
  }
  return best;
}

function drawQuestions(pool, count, quotas) {
  const picked = [];
  const claimed = new Set();
  const used = new Set();

  const fits = (q) => q.claims.every((c) => !claimed.has(c) && !used.has(c))
    && q.uses.every((u) => !claimed.has(u));
  const take = (q) => {
    picked.push(q);
    q.claims.forEach((c) => claimed.add(c));
    q.uses.forEach((u) => used.add(u));
  };

  const candidates = shuffle(pool);
  for (const [domain, quota] of shuffle(Object.entries(quotas || {}))) {
    let n = 0;
    for (const q of candidates) {
      if (n >= quota || picked.length >= count) break;
      if (q.domain === domain && !picked.includes(q) && fits(q)) {
        take(q);
        n++;
      }
    }
  }
  for (const q of candidates) {
    if (picked.length >= count) break;
    if (!picked.includes(q) && fits(q)) take(q);
  }
  return picked;
}

/** Return the directory holding the scripts/ of a source lab. */
function sourceScriptsDir(sourceDir) {
  if (fs.existsSync(path.join(sourceDir, 'scripts'))) return sourceDir;
  if (extractedSources.has(sourceDir)) return extractedSources.get(sourceDir);
  const archive = path.join(sourceDir, 'assets.tar.gz');
  if (!fs.existsSync(archive)) throw new Error(`No scripts found for ${sourceDir}`);
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ckx-src-'));
  execFileSync('tar', ['-xzf', archive, '-C', dir]);
  extractedSources.set(sourceDir, dir);
  return dir;
}

/** Split answers.md into { questionId: sectionText }. */
function answerSections(file) {
  const sections = {};
  if (!fs.existsSync(file)) return sections;
  let current = null;
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = line.match(/^## Question (\d+)\b/);
    if (m) {
      current = m[1];
      sections[current] = [line];
    } else if (current) {
      sections[current].push(line);
    }
  }
  // drop the horizontal rule that separates a section from the next one
  Object.keys(sections).forEach((k) => {
    sections[k] = sections[k].join('\n').trim().replace(/(\n-{3,}\s*)+$/, '').trim();
  });
  return sections;
}

/** Point /tmp/exam/qN and the host cka-qN of a task at its new number. */
function renumber(text, fromId, toId) {
  return text
    .replace(new RegExp(`/tmp/exam/q${fromId}(?![0-9])`, 'g'), `/tmp/exam/q${toId}`)
    .replace(new RegExp(`cka-q${fromId}(?![0-9])`, 'g'), `cka-q${toId}`);
}

function removeOldAttempts(attemptsDir, keepId) {
  if (!fs.existsSync(attemptsDir)) return;
  const dirs = fs.readdirSync(attemptsDir)
    .filter((d) => d !== keepId)
    .map((d) => ({ d, t: fs.statSync(path.join(attemptsDir, d)).mtimeMs }))
    .sort((a, b) => b.t - a.t);
  dirs.slice(KEEP_ATTEMPTS - 1).forEach(({ d }) => {
    fs.rmSync(path.join(attemptsDir, d), { recursive: true, force: true });
  });
}

/**
 * Build the lab of one attempt.
 * @param {string} examId - The exam ID
 * @param {string} assetPath - Asset path of the random lab (relative to cwd)
 * @param {Object} config - The random lab's config.json
 * @returns {{assetPath: string, config: Object, questionCount: number}}
 */
function buildRandomExam(examId, assetPath, config) {
  const cwd = process.cwd();
  const randomDir = path.join(cwd, assetPath);
  const settings = config.random || {};
  const count = settings.questionCount || 16;
  const pool = readJson(path.join(randomDir, settings.pool || 'pool.json')).questions;

  const sources = {};
  const loadSource = (source) => {
    if (!sources[source]) {
      const dir = path.join(cwd, 'assets', 'exams', source);
      const cfg = readJson(path.join(dir, 'config.json'));
      const questions = readJson(path.join(dir, cfg.questions || 'assessment.json')).questions;
      sources[source] = {
        dir,
        questions: Object.fromEntries(questions.map((q) => [String(q.id), q])),
        answers: answerSections(path.join(dir, 'answers.md')),
        scripts: sourceScriptsDir(dir)
      };
    }
    return sources[source];
  };

  // only keep tasks that still exist in their lab
  const available = pool.filter((p) => {
    try {
      return Boolean(loadSource(p.source).questions[p.id]);
    } catch (e) {
      logger.warn(`Random exam: skipping ${p.source}`, { error: e.message });
      return false;
    }
  });
  const picked = pickQuestions(available, count, settings.domainQuota);
  if (picked.length === 0) throw new Error('Random exam: no task available');

  // order like a real exam: mixed domains, not grouped by source
  const ordered = shuffle(picked);

  const attemptRel = path.join(assetPath, 'attempts', examId);
  const attemptDir = path.join(cwd, attemptRel);
  const buildDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ckx-random-'));
  fs.mkdirSync(path.join(buildDir, 'scripts', 'setup'), { recursive: true });
  fs.mkdirSync(path.join(buildDir, 'scripts', 'validation'), { recursive: true });
  fs.mkdirSync(attemptDir, { recursive: true });

  const labNames = settings.labNames || {};
  const questions = [];
  const answers = [
    '# CKA Random: Solutions for this attempt',
    '',
    'Each task below comes from one of the CK-X CKA exams; the heading says which one. '
      + 'Paths and host names were renumbered for this attempt.',
    ''
  ];

  ordered.forEach((p, index) => {
    const newId = String(index + 1);
    const src = loadSource(p.source);
    const q = src.questions[p.id];
    const prefix = p.source.replace(/[^a-z0-9]/gi, '');

    // setup script: q01_setup.sh, q02_setup.sh ... (prepare-exam-env runs q*_setup.sh in order)
    const setupFile = path.join(src.scripts, 'scripts', 'setup', `q${p.id}_setup.sh`);
    if (fs.existsSync(setupFile)) {
      const target = path.join(buildDir, 'scripts', 'setup', `q${newId.padStart(2, '0')}_setup.sh`);
      fs.writeFileSync(target, renumber(fs.readFileSync(setupFile, 'utf8'), p.id, newId), { mode: 0o755 });
    }

    const verification = q.verification.map((v) => {
      const name = `${prefix}_${v.verificationScriptFile}`;
      const file = path.join(src.scripts, 'scripts', 'validation', v.verificationScriptFile);
      fs.writeFileSync(path.join(buildDir, 'scripts', 'validation', name),
        renumber(fs.readFileSync(file, 'utf8'), p.id, newId), { mode: 0o755 });
      return { ...v, verificationScriptFile: name };
    });

    questions.push({
      ...q,
      id: newId,
      machineHostname: `cka-q${newId}`,
      question: renumber(q.question, p.id, newId),
      verification,
      source: { lab: p.source, question: p.id }
    });

    const from = `${labNames[p.source] || p.source}, task ${p.id}`;
    const section = (src.answers[p.id] || `## Question ${p.id}\n\nNo solution available.`)
      .replace(/^## Question \d+:?\s*/, `## Question ${newId}: `);
    answers.push('---', '', renumber(section, p.id, newId).replace(/\n/, `\n\n*From ${from}.*\n`), '');
  });

  execFileSync('tar', ['-czf', path.join(attemptDir, 'assets.tar.gz'), '-C', buildDir, 'scripts']);
  fs.rmSync(buildDir, { recursive: true, force: true });

  fs.writeFileSync(path.join(attemptDir, 'assessment.json'), JSON.stringify({ questions }, null, 2));
  fs.writeFileSync(path.join(attemptDir, 'answers.md'), answers.join('\n'));
  const attemptConfig = {
    ...config,
    questions: 'assessment.json',
    answers: path.join(attemptRel, 'answers.md'),
    sourceLab: config.lab
  };
  delete attemptConfig.random;
  fs.writeFileSync(path.join(attemptDir, 'config.json'), JSON.stringify(attemptConfig, null, 2));

  removeOldAttempts(path.join(randomDir, 'attempts'), examId);

  logger.info(`Random exam ${examId}: ${questions.length} tasks`, {
    tasks: questions.map((q) => `${q.source.lab}/${q.source.question} -> Q${q.id}`)
  });
  return { assetPath: attemptRel, config: attemptConfig, questionCount: questions.length };
}

module.exports = { buildRandomExam, pickQuestions };
